/// <reference types="@cloudflare/workers-types" />
/**
 * Worker entry (bundled by wrangler, outside the Next.js typecheck): the OpenNext-generated Next.js handler plus the minute cron
 * that forwards the scheduler tick to the app itself, so SLA detection and
 * scheduled sends run without the Neon ops Function. The same cron steps agent
 * runs through a second route, in parallel, so a slow Claude call never delays the tick.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";

interface Env {
  WORKER_SELF_REFERENCE: Fetcher;
  JOB_SECRET?: string;
  NEXT_PUBLIC_APP_URL?: string;
}

export default {
  fetch: handler.fetch,
  async scheduled(_controller: ScheduledController, env: Env, _ctx: ExecutionContext) {
    if (!env.JOB_SECRET) {
      console.error("[cron] JOB_SECRET is not set; the tick cannot authenticate.");
      return;
    }
    const origin = env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, "") || "https://mesquared-os.workers.dev";
    const secret = env.JOB_SECRET;
    // Awaited, not waitUntil: the cron invocation must stay alive for as long as the jobs run (it has a 15-minute wall-clock
    // budget), and a job cut short would leave what it claimed to its lease timeout.
    const run = async (name: string, path: string) => {
      try {
        const res = await env.WORKER_SELF_REFERENCE.fetch(`${origin}${path}`, { method: "POST", headers: { authorization: `Bearer ${secret}`, "content-type": "application/json" }, body: "{}", signal: AbortSignal.timeout(10 * 60_000) });
        const text = (await res.text()).slice(0, 300);
        if (!res.ok) console.error(`[cron] ${name} returned ${res.status}: ${text}`);
        else console.log(`[cron] ${name} ${text}`);
      } catch (error) {
        console.error(`[cron] ${name} failed: ${error instanceof Error ? error.message : String(error)}`);
      }
    };
    await Promise.all([run("tick", "/api/jobs/tick"), run("agents", "/api/jobs/agents")]);
  },
} satisfies ExportedHandler<Env>;

// Durable Object classes OpenNext may reference once an incremental cache or queue is configured; harmless otherwise.
// @ts-expect-error generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "../.open-next/worker.js";
